mapper.select:
select d.*,u.username from diseased_trees d left join users u on d.survey_id = u.user_id


        d.species like concat('%' || #{species} || '%')


        and d.grade = #{grade}


        and d.survey_date between #{start} and #{end}


        and d.survey_id = #{surveyId}



        and u.username = #{username}
